"""COBOL test harness generation for programs with a LINKAGE SECTION.

The harness ACCEPTs one input line per USING parameter, CALLs the program and
DISPLAYs every parameter followed by an end marker. The generated Python
``app/cli.py --mode harness`` implements exactly the same protocol, so both
sides receive identical bytes and produce comparable output.
"""

from __future__ import annotations

from ..cobol import ir

END_MARK = "*PHOENIX-END*"
HARNESS_ID = "PHXHARNS"


def harness_source(prog: ir.Program) -> str:
    index = prog.item_index()
    lines = [
        "      * Generated by COBOL Phoenix - differential test harness.",
        "       IDENTIFICATION DIVISION.",
        f"       PROGRAM-ID. {HARNESS_ID}.",
        "       DATA DIVISION.",
        "       WORKING-STORAGE SECTION.",
    ]
    names = []
    for i, uid in enumerate(prog.using, start=1):
        size = index[uid].size
        name = f"PHX-P{i}"
        names.append(name)
        lines.append(f"       01  {name} PIC X({size}).")
    lines.append("       PROCEDURE DIVISION.")
    for n in names:
        lines.append(f"           ACCEPT {n}")
    lines.append(f'           CALL "{prog.program_id}" USING')
    for n in names:
        lines.append(f"               {n}")
    lines.append("           END-CALL")
    for n in names:
        lines.append(f"           DISPLAY {n}")
    lines.append(f'           DISPLAY "{END_MARK}"')
    lines.append("           STOP RUN.")
    return "\n".join(lines) + "\n"


def split_harness_output(stdout: str, nparams: int) -> tuple[list[str], list[str] | None]:
    """Return (program display lines, parameter lines or None if no end marker)."""
    lines = stdout.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    if END_MARK not in lines:
        return lines, None
    end = len(lines) - 1 - lines[::-1].index(END_MARK)
    params = lines[end - nparams : end]
    return lines[: end - nparams], params
